import React from "react";import {expect,test,vi} from "vitest";import {render,screen} from "@testing-library/react";import userEvent from "@testing-library/user-event";import {WatchToggle} from "./WatchToggle";
test("początkowo użytkownik może wybrać obserwowanie",()=>{render(<WatchToggle/>);expect(screen.getByRole("button",{name:"Obserwuj ticket"})).toHaveAttribute("aria-pressed","false");});
test("kliknięcie zmienia widoczny wybór i powiadamia odbiorcę",async()=>{const user=userEvent.setup(),onChange=vi.fn();render(<WatchToggle onChange={onChange}/>);await user.click(screen.getByRole("button",{name:"Obserwuj ticket"}));expect(screen.getByRole("button",{name:"Przestań obserwować ticket"})).toHaveAttribute("aria-pressed","true");expect(onChange).toHaveBeenCalledExactlyOnceWith(true);});
test("drugi klik przywraca niewybrany stan",async()=>{const user=userEvent.setup();render(<WatchToggle/>);await user.click(screen.getByRole("button",{name:"Obserwuj ticket"}));await user.click(screen.getByRole("button",{name:"Przestań obserwować ticket"}));expect(screen.getByRole("button",{name:"Obserwuj ticket"})).toHaveAttribute("aria-pressed","false");});
test("nieaktywny przycisk nie zmienia wyboru",async()=>{const user=userEvent.setup(),onChange=vi.fn();render(<WatchToggle disabled onChange={onChange}/>);const button=screen.getByRole("button",{name:"Obserwuj ticket"});expect(button).toBeDisabled();await user.click(button);expect(button).toHaveAttribute("aria-pressed","false");expect(onChange).not.toHaveBeenCalled();});
test("początkowy aktywny wybór można wyłączyć",async()=>{const user=userEvent.setup();render(<WatchToggle initialWatching/>);await user.click(screen.getByRole("button",{name:"Przestań obserwować ticket"}));expect(screen.getByRole("button",{name:"Obserwuj ticket"})).toHaveAttribute("aria-pressed","false");});

